 64→function getDisplayTitle(job: PastJob): string {
 65→  if (job.title) return job.title;
 66→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 67→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 68→}
